#!/bin/bash
# Build the CellBender denoiser's environment, <env-root>/cellbender, from conf/env/cellbender.lock.txt.
#
# Usage:
#   conf/env/install_cellbender.sh <env-root>
#   conf/env/install_cellbender.sh --check     read the lock and refuse it as a build would; build nothing
#
# <env-root> is the directory given to setup/install_env.sh --prefix, which calls this script for
# --with-cellbender; conf/env/install_cs_cb.sh calls it for its `cellbender` component. It is the one
# recipe for this environment. There used to be two, and neither named a torch.
#
# THE LOCK holds every package of the environment's closure at one exact version, for linux x86_64 only.
# It is applied with `pip install --no-deps`, so pip resolves nothing, and every installed version is then
# compared with it. An environment that already exists is compared and never modified: re-running cannot
# change an environment something may be using, and one holding another torch is refused, not reused.
#
# THE THREE VERSIONS REQUIRED HERE, whatever the lock says. A lock is regenerated by a resolver; these are
# decisions, and a lock that disagrees with one is refused before anything is built. Each says where it
# comes from (BASIS below; --check prints it), because only two of them are on record:
#
#   cellbender 0.3.2   recorded: the release that made the denoised objects this pipeline was calibrated on
#   torch 2.5.1        recorded: the torch of the environment that made them. With no torch named, pip took
#                      the newest - 2.14.1 on one cohort's first build - and the same recipe made a different
#                      denoiser from the one calibrated (single-cell-harness ADR-0027, finding Q9)
#   numpy 1.26.4       drafted: the numpy pinned together with torch when Q9's fix was drafted. That
#                      environment's own numpy is NOT on record; a build compared with it will say.
#
# WHAT THE PIN IS NOT: it is not shown to let CellBender 0.3.2 write its checkpoint. pyro attaches a weakref
# (`.unconstrained`) to every parameter it manages, recent torch pickles a parameter's `__dict__`, and
# `torch.save` then fails, after the last training epoch. The calibration runs met that failure in the
# environment whose torch is pinned here, and saved through a wrapper outside this repository.
# adapters/cellbender.py refuses the empty result; it does not work around the cause (KNOWN_ISSUES).
#
# Environment:
#   SCQC_CONDA   package manager to use; setup/install_env.sh passes the one it discovered

set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LOCK="$HERE/cellbender.lock.txt"
REQUIRES=(cellbender==0.3.2 torch==2.5.1 numpy==1.26.4)
BASIS=("recorded: the release that made the denoised objects this pipeline was calibrated on"
       "recorded: the torch of the environment that made them (single-cell-harness ADR-0027, Q9)"
       "drafted: pinned with torch when Q9's fix was drafted; that environment's own numpy is not on record")
# shellcheck source=lock.sh
. "$HERE/lock.sh"

usage() {
    awk 'NR == 1 { next } /^#/ { sub(/^# ?/, ""); print; next } { exit }' "${BASH_SOURCE[0]}"
    exit "${1:-0}"
}

check() {
    local i
    require_pins "$LOCK" cellbender "${REQUIRES[@]}" || return 1
    check_lock "$LOCK" cellbender || return 1
    echo "    and it pins the versions this script requires, each with where it comes from:"
    for i in "${!REQUIRES[@]}"; do
        echo "      ${REQUIRES[$i]%%==*} ${REQUIRES[$i]#*==} - ${BASIS[$i]}"
    done
}

case "${1:-}" in
    --check)       check || exit 1; exit 0 ;;
    -h|--help)     usage 0 ;;
    "")            echo "usage: install_cellbender.sh <env-root> | --check" >&2; exit 2 ;;
    /*)            ROOT="$1" ;;
    *)             echo "ERROR: <env-root> must be an absolute path (got '$1')" >&2; exit 2 ;;
esac

echo "--- the lock ---"
check || exit 1
WANT_PY="$(lock_python "$LOCK")"
ENVDIR="$ROOT/cellbender"

if [ -d "$ENVDIR" ] && [ ! -x "$ENVDIR/bin/python" ]; then
    # EXISTING IS NOT COMPLETE (single-cell-harness ADR-0027): a build killed mid-transaction leaves the
    # directory without its interpreter. Refused by default; with setup/install_env.sh --repair
    # (SCQC_REPAIR=1; harness autodev W020, B1-108) the shape an interrupted build leaves - conda-meta/
    # present, the interpreter absent - is removed and built again, and the removal is printed.
    if [ "${SCQC_REPAIR:-0}" = "1" ] && [ -d "$ENVDIR/conda-meta" ]; then
        echo "  [repair] $ENVDIR holds conda-meta/ and no bin/python - the remains of an interrupted build;"
        echo "           removed, and it is built again"
        rm -rf "$ENVDIR"
    else
        echo "ERROR: $ENVDIR exists but has no bin/python - the remains of an interrupted build." >&2
        if [ -d "$ENVDIR/conda-meta" ]; then
            echo "       Run setup/install_env.sh again with --repair to remove and rebuild it, or remove it" >&2
            echo "       yourself:  rm -rf '$ENVDIR'" >&2
        else
            echo "       It holds no conda-meta/, so it is not known to be a build; move it aside and run again." >&2
        fi
        exit 1
    fi
fi

made=0
if [ -d "$ENVDIR" ]; then
    echo "  [skip] cellbender exists at $ENVDIR: compared with the lock, not modified"
else
    MM="${SCQC_CONDA:-}"
    if [ -z "$MM" ]; then
        for c in micromamba mamba conda; do
            if command -v "$c" >/dev/null 2>&1; then MM="$(command -v "$c")"; break; fi
        done
    fi
    if [ -z "$MM" ]; then
        mkdir -p "$ROOT/bin" || exit 1
        echo "--- no conda, mamba or micromamba found; bootstrapping micromamba into $ROOT/bin ---"
        ( cd "$ROOT" && curl -Ls https://micro.mamba.pm/api/micromamba/linux-64/latest | tar -xj bin/micromamba )
        chmod +x "$ROOT/bin/micromamba" 2>/dev/null
        MM="$ROOT/bin/micromamba"
    fi
    [ -x "$MM" ] || { echo "ERROR: package manager '$MM' is not executable" >&2; exit 1; }
    export MAMBA_ROOT_PREFIX="${MAMBA_ROOT_PREFIX:-$ROOT/mamba}"
    echo "  [make] cellbender (python $WANT_PY) with $MM"
    # conda-forge alone: a channel list from an rc file must not decide which interpreter build arrives.
    "$MM" create -y -p "$ENVDIR" --override-channels -c conda-forge "python=$WANT_PY" >/dev/null \
        || { echo "ERROR: the package manager could not create $ENVDIR" >&2; exit 1; }
    made=1
fi

GOT_PY="$(env_python "$ENVDIR/bin/python")"
if [ "$GOT_PY" != "$WANT_PY" ]; then
    echo "ERROR: $ENVDIR has python $GOT_PY; conf/env/cellbender.lock.txt was resolved against $WANT_PY." >&2
    echo "       Remove it and run again, or build into a new <env-root>." >&2
    exit 1
fi
echo "  python $GOT_PY, matching the lock"

if [ "$made" -eq 1 ]; then
    echo "--- pip install --no-deps -r conf/env/cellbender.lock.txt (nothing is resolved) ---"
    apply_lock "$ENVDIR/bin/python" "$LOCK" \
        || { echo "ERROR: pip could not install conf/env/cellbender.lock.txt into $ENVDIR" >&2; exit 1; }
fi

echo "--- every installed version against the lock ---"
if ! verify_lock "$ENVDIR/bin/python" "$LOCK" cellbender; then
    echo "ERROR: REFUSED - $ENVDIR is not the environment conf/env/cellbender.lock.txt describes." >&2
    if [ "$made" -eq 0 ]; then
        echo "       It existed before this run and was not modified. Remove it and run again, or build" >&2
        echo "       into a new <env-root>." >&2
    fi
    exit 1
fi
